body:
### Tested versions

v4.5.stable.official [876b29033]

### System information

Godot v4.5.stable - Windows 10 (build 19045) - Multi-window, 2 monitors - Vulkan (Forward+) - dedicated NVIDIA GeForce GTX 970 (NVIDIA; 32.0.15.7242) - 12th Gen Intel(R) Core(TM) i5-12500 (12 threads) - 31.77 GiB memory

### Issue description

Bug randomly occur with error:
```
E 0:00:00:717   _physics_process: Invalid operands 'Nil' and 'Vector2' in operator '*'.
  <GDScript Source>test.gd:27 @ _physics_process()
  <Stack Trace> test.gd:27 @ _physics_process()
```

I cannot lauch scene but before I didnt have problem with script below:

```gdscript
extends CharacterBody2D
@export var speed = 100
@export var sfx_walk_dirt = AudioStream
@export var sfx_walk_grass = AudioStream
@export var sfx_walk_stone = AudioStream
@onready var _animated_sprite = $Sprite

var footstep_frames : Array = [1,3]

func _process(_delta):
	if Input.is_action_pressed("ui_right"):
		_animated_sprite.flip_h = false
		_animated_sprite.play("side")
	elif Input.is_action_pressed("ui_up"):
		_animated_sprite.play("up")
	elif Input.is_action_pressed("ui_down"):
		_animated_sprite.play("down")
	elif Input.is_action_pressed("ui_left"):
		_animated_sprite.flip_h = true
		_animated_sprite.play("side")
	else:
		_animated_sprite.stop()

func _physics_process(_delta: float) -> void:
	velocity = Vector2.ZERO
	var direction = get_direction()
	velocity = speed * direction
	move_and_slide()

func get_direction() -> Vector2:
	var direction: = Vector2.ZERO
	if Input.is_action_pressed("ui_right") || Input.is_action_pressed("ui_left"):
		direction.x = int(Input.is_action_pressed("ui_right")) - int(Input.is_action_pressed("ui_left"))
		print(direction.x,_animated_sprite)
	elif Input.is_action_pressed("ui_down") || Input.is_action_pressed("ui_up"):
		direction.y = int(Input.is_action_pressed("ui_down")) - int(Input.is_action_pressed("ui_up"))
		print(direction.y,_animated_sprite)
	return direction

func load_sfx(sfx_to_load):
	if %sfx_player.stream != sfx_to_load:
		%sfx_player.stop()
		%sfx_player.stream = sfx_to_load

func _on_animated_sprite_2d_frame_changed():
	if %Sprite.animation == "Idle": return
	_on_grass_area_body_exided(CharacterBody2D)

	if %Sprite.frame in footstep_frames: %sfx_player.play()


func _on_grass_area_body_exided(body):
	if body != self:
		load_sfx(sfx_walk_grass)
	else:load_sfx(sfx_walk_dirt)
	pass # Replace with function body.
```

"`@export var speed = 100`" seems to be reason because if I change speed to number in script to:
```gdscript
func _physics_process(_delta: float) -> void:
	velocity = Vector2.ZERO
	var direction = get_direction()
	velocity = 100 * direction
	move_and_slide()
```
it work fine. 

### Steps to reproduce

work on project 3 hours normally
try to test something and play scene
error occur

